/** An in-memory journal scoped to one replay. Input operations are immutable. */
import {equivalent} from "./request.mjs";

export class Ledger {
  constructor() {
    this.byId = new Map();
    this.events = [];
  }

  usage(tenant, day) {
    let used = 0;
    for (const entry of this.byId.values()) {
      if (entry.tenant === tenant && entry.day === day && entry.active) {
        used += entry.units;
      }
    }
    return used;
  }

  inspect(id) {
    const entry = this.byId.get(id);
    return entry ? {...entry} : null;
  }

  reserve(request, cap) {
    const previous = this.byId.get(request.id);
    if (previous) {
      if (!equivalent(previous, request)) {
        return {status: "conflict", id: request.id};
      }
      return {status: previous.active ? "replay" : "cancelled", id: request.id};
    }
    const used = this.usage(request.tenant, request.day);
    if (used + request.units > cap) {
      return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
    }
    this.byId.set(request.id, {...request, active: true});
    this.events.push({type: "booked", ...request});
    return {status: "booked", id: request.id, remaining: cap - used - request.units};
  }

  cancel(id) {
    const entry = this.byId.get(id);
    if (!entry) return {status: "missing", id};
    if (!entry.active) return {status: "replay", id};
    entry.active = false;
    this.events.push({type: "cancelled", id});
    return {status: "cancelled", id};
  }

  summary() {
    const occupied = [];
    for (const entry of this.byId.values()) {
      if (entry.active) occupied.push({...entry});
    }
    occupied.sort((a, b) => a.id.localeCompare(b.id));
    return {occupied, events: this.events.map(event => ({...event}))};
  }
}
import {readFileSync} from "node:fs";
import {quantity} from "./request.mjs";

const path = new URL("../config/catalog.json", import.meta.url);

export function readCatalog(location = path) {
  const obj = JSON.parse(readFileSync(location, "utf8"));
  const cap = quantity(obj.default, "default");
  const overrides = new Map();
  for (const [tenant, value] of Object.entries(obj.studios)) {
    overrides.set(tenant, quantity(value, "studio quota"));
  }
  return {default: cap, studios: overrides};
}

export function reserve(ledger, request, cap = readCatalog().default) {
  return ledger.reserve(request, cap);
}
/** Validate incoming booking requests before they reach the reservation engine. */
export class InputError extends Error {
  constructor(field, message) {
    super(field + " " + message);
    this.field = field;
  }
}

export function name(value, field) {
  if (typeof value !== "string" || !/^[a-z][a-z0-9-]{0,47}$/.test(value)) {
    throw new InputError(field, "must be a lowercase identifier");
  }
  return value;
}

export function quantity(value, field) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new InputError(field, "must be a positive integer");
  }
  return value;
}

export function day(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    throw new InputError("day", "must use YYYY-MM-DD");
  }
  const date = new Date(value + "T00:00:00Z");
  if (Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== value) {
    throw new InputError("day", "is not a calendar date");
  }
  return value;
}

export function booking(value) {
  if (value == null || typeof value !== "object" || Array.isArray(value)) {
    throw new InputError("request", "must be an object");
  }
  return {
    id: name(value.id, "id"),
    tenant: name(value.tenant, "tenant"),
    day: day(value.day),
    units: quantity(value.units, "units")
  };
}

export function equivalent(a, b) {
  return a.id === b.id && a.tenant === b.tenant &&
         a.day === b.day && a.units === b.units;
}
